let saved = [];
try {
  const raw = localStorage.getItem("citajSrpskiWords");
  const parsed = raw ? JSON.parse(raw) : [];
  saved = Array.isArray(parsed) ? parsed : [];
} catch (e) {
  saved = [];
}


const REVIEW_INTERVALS = [0, 1, 2, 4, 8, 16]; // дни для коробок 1–5

function normalizeSavedWords(){
  let changed = false;
  saved = saved.map(x => {
    const y = {...x};
    if (!Number.isInteger(y.box) || y.box < 1 || y.box > 5) { y.box = 1; changed = true; }
    if (!y.nextReview) { y.nextReview = Date.now(); changed = true; }
    if (!y.translation || y.translation === 'Перевод пока не добавлен') {
      const tr = DICT[y.word];
      if (tr) { y.translation = tr; changed = true; }
    }
    return y;
  });
  if (changed) localStorage.setItem('citajSrpskiWords', JSON.stringify(saved));
}
normalizeSavedWords();

const $ = id => document.getElementById(id);
const normalize = w => w.toLowerCase().replace(/[„“”«».,!?;:()\[\]{}]/g, "").trim();

function save(){
  localStorage.setItem("citajSrpskiWords", JSON.stringify(saved));
  const count = $("count");
  if (count) count.textContent = saved.length;
}

function view(id){
  document.querySelectorAll("main section").forEach(s => s.classList.add("hide"));
  const section = $(id);
  if (section) section.classList.remove("hide");
  window.scrollTo(0,0);
}

function texts(){
  $("list").innerHTML = TEXTS.map((t,i) => `
    <div class="card">
      <div class="tag">${t.level}</div>
      <h3>${t.title}</h3>
      <p>${t.ru}</p>
      <p class="muted">Большой учебный текст · около ${t.text.split(/[.!?]+/).filter(Boolean).length} предложений</p>
      <button type="button" class="read-text" data-index="${i}">Читать</button>
    </div>`).join("");
}

function tokenize(text){ return text.split(/(\s+)/); }

function renderText(text){
  $("text").innerHTML = tokenize(text).map(part => {
    if (/^\s+$/.test(part)) return part;
    const clean = normalize(part);
    if (!clean) return part;
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "word";
    btn.dataset.word = clean;
    btn.textContent = part;
    return btn.outerHTML;
  }).join("");
}

function openText(i){
  const t = TEXTS[i];
  $("title").textContent = t.title;
  $("level").textContent = `${t.level} · ${t.ru}`;
  $("source").textContent = t.source;
  renderText(t.text);
  $("popup").classList.add("hide");
  view("reader");
}

function speakWord(w){
  if (!('speechSynthesis' in window)) {
    alert('Озвучка не поддерживается этим браузером.');
    return;
  }
  window.speechSynthesis.cancel();
  const u = new SpeechSynthesisUtterance(w);
  u.lang = 'sr-RS';
  u.rate = 0.82;
  u.pitch = 1;
  window.speechSynthesis.speak(u);
}

function speakText(text){
  if (!('speechSynthesis' in window)) {
    alert('Озвучка не поддерживается этим браузером.');
    return;
  }
  window.speechSynthesis.cancel();
  const u = new SpeechSynthesisUtterance(text);
  u.lang = 'sr-RS';
  u.rate = 0.88;
  window.speechSynthesis.speak(u);
}

function word(w){
  const translation = DICT[w] || 'Перевод пока не добавлен';
  const exists = saved.some(x => x.word === w);
  $('popup').innerHTML = `
    <div class="popup-title">${w}</div>
    <div class="popup-translation">${translation}</div>
    <div class="popup-actions">
      <button type="button" id="speak-word">🔊 Слушать</button>
      <button type="button" id="add-word-button">${exists ? '✓ Уже в моих словах' : 'Добавить в мои слова'}</button>
    </div>`;
  $('popup').classList.remove('hide');
  $('speak-word').addEventListener('click', () => speakWord(w));
  const addButton = $('add-word-button');
  if (addButton && !exists) addButton.addEventListener('click', () => addWord(w));
}

function addWord(w){
  if (!saved.some(x => x.word === w)) {
    saved.push({word:w, translation:DICT[w] || 'Перевод пока не добавлен', added:new Date().toISOString(), box:1, nextReview:Date.now()});
    save();
  }
  word(w);
}

function words(){
  const due = getDueWords().length;
  $('saved').innerHTML = `
    <div class="card review-card">
      <h3>Тренировки</h3>
      <p>Здесь можно не только повторять слова по интервалам, но и активно вспоминать их.</p>
      <p><b>К повторению сегодня: ${due}</b></p>
      <div class="training-buttons">
        <button type="button" id="start-review">🔁 Интервальное повторение</button>
        <button type="button" id="start-choice">🎯 Слово → перевод</button>
        <button type="button" id="start-reverse">🧠 Перевод → слово</button>
      </div>
      <hr>
      <button type="button" id="export-words">💾 Сохранить мои слова</button>
      <button type="button" id="import-words">📥 Загрузить мои слова</button>
      <input id="import-file" type="file" accept="application/json" class="hide">
      <p class="muted small-note">Твои слова остаются в localStorage при обычном обновлении сайта. Резервная копия нужна на случай очистки данных браузера или смены устройства.</p>
    </div>
    <div class="card">
      <h3>Мои слова: ${saved.length}</h3>
      ${saved.length ? saved.map((x,i) => `<div class="row"><b>${x.word}</b><span> — ${x.translation}</span><span class="box-label">Коробка ${x.box || 1}</span><button type="button" class="small speak-saved" data-word="${x.word}">🔊</button><button type="button" class="small remove-word" data-index="${i}">Удалить</button></div>`).join('') : `<p>Словарь пока пуст.</p>`}
    </div>`;
  view('words');

  $('start-review').addEventListener('click', startReview);
  $('start-choice').addEventListener('click', () => startExercise('choice'));
  $('start-reverse').addEventListener('click', () => startExercise('reverse'));
  $('export-words').addEventListener('click', exportWords);
  $('import-words').addEventListener('click', () => $('import-file').click());
  $('import-file').addEventListener('change', importWords);
  document.querySelectorAll('.speak-saved').forEach(b => b.addEventListener('click', () => speakWord(b.dataset.word)));
}

let exerciseQueue = [];
let exerciseIndex = 0;
let exerciseType = 'choice';

function shuffle(arr){
  const a=[...arr];
  for(let i=a.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); [a[i],a[j]]=[a[j],a[i]]; }
  return a;
}

function startExercise(type){
  if (saved.length < 2) {
    alert('Для этой тренировки нужно хотя бы 2 слова в «Моих словах».');
    return;
  }
  exerciseType = type;
  exerciseQueue = shuffle(saved).slice(0, Math.min(10, saved.length)).map(x => x.word);
  exerciseIndex = 0;
  renderExercise();
  view('review');
}

function renderExercise(){
  if (exerciseIndex >= exerciseQueue.length) {
    $('review-content').innerHTML = `<div class="card"><h2>Тренировка закончена 🎉</h2><p>Ты прошёл ${exerciseQueue.length} заданий.</p><button type="button" id="exercise-finish">Вернуться к моим словам</button></div>`;
    $('exercise-finish').addEventListener('click', words);
    return;
  }
  const item = saved.find(x => x.word === exerciseQueue[exerciseIndex]);
  if (!item) { exerciseIndex++; renderExercise(); return; }
  if (exerciseType === 'choice') renderChoice(item); else renderReverse(item);
}

function renderChoice(item){
  const others = shuffle(saved.filter(x => x.word !== item.word)).slice(0,3);
  const options = shuffle([item, ...others]);
  $('review-content').innerHTML = `<div class="card review-card"><p class="muted">Слово → перевод · ${exerciseIndex+1} из ${exerciseQueue.length}</p><div class="flash-word">${item.word}</div><button type="button" id="exercise-speak">🔊 Послушать</button><div class="options">${options.map((x,i)=>`<button type="button" class="option" data-answer="${i}">${x.translation}</button>`).join('')}</div><div id="exercise-feedback" class="feedback"></div></div>`;
  $('exercise-speak').addEventListener('click',()=>speakWord(item.word));
  document.querySelectorAll('.option').forEach((b,i)=>b.addEventListener('click',()=>{
    const chosen=options[i]; const ok=chosen.word===item.word;
    document.querySelectorAll('.option').forEach(x=>x.disabled=true);
    $('exercise-feedback').innerHTML=ok ? '<b>✓ Правильно</b>' : `<b>✗ Не совсем.</b> Правильный ответ: ${item.translation}`;
    if(!ok){ item.box=1; item.nextReview=Date.now(); save(); }
    setTimeout(()=>{exerciseIndex++; renderExercise();}, 850);
  }));
}

function renderReverse(item){
  const others = shuffle(saved.filter(x => x.word !== item.word)).slice(0,3);
  const options = shuffle([item, ...others]);
  $('review-content').innerHTML = `<div class="card review-card"><p class="muted">Перевод → слово · ${exerciseIndex+1} из ${exerciseQueue.length}</p><div class="flash-word">${item.translation}</div><div class="options">${options.map((x,i)=>`<button type="button" class="option" data-answer="${i}">${x.word}</button>`).join('')}</div><div id="exercise-feedback" class="feedback"></div></div>`;
  document.querySelectorAll('.option').forEach((b,i)=>b.addEventListener('click',()=>{
    const chosen=options[i]; const ok=chosen.word===item.word;
    document.querySelectorAll('.option').forEach(x=>x.disabled=true);
    $('exercise-feedback').innerHTML=ok ? '<b>✓ Правильно</b>' : `<b>✗ Правильный ответ: ${item.word}</b>`;
    if(!ok){ item.box=1; item.nextReview=Date.now(); save(); }
    setTimeout(()=>{exerciseIndex++; renderExercise();}, 850);
  }));
}

function getDueWords(){
  const now = Date.now();
  return saved.filter(x => !x.nextReview || x.nextReview <= now);
}

let reviewQueue = [];
let reviewIndex = 0;
let reviewRevealed = false;

function startReview(){
  reviewQueue = getDueWords().map(x => x.word);
  reviewIndex = 0;
  reviewRevealed = false;
  if (!reviewQueue.length) {
    alert('На сегодня слов для повторения нет. Добавь новые слова или возвращайся позже.');
    return;
  }
  renderReviewCard();
  view('review');
}

function renderReviewCard(){
  if (reviewIndex >= reviewQueue.length) {
    $('review-content').innerHTML = `<div class="card"><h2>Повторение закончено 🎉</h2><p>Ты прошёл ${reviewQueue.length} карточек.</p><button type="button" id="review-finish">Вернуться к моим словам</button></div>`;
    $('review-finish').addEventListener('click', words);
    return;
  }
  const w = reviewQueue[reviewIndex];
  const item = saved.find(x => x.word === w);
  if (!item) { reviewIndex++; renderReviewCard(); return; }
  reviewRevealed = false;
  $('review-content').innerHTML = `
    <div class="card review-card">
      <p class="muted">Карточка ${reviewIndex+1} из ${reviewQueue.length} · коробка ${item.box || 1}</p>
      <div class="flash-word">${item.word}</div>
      <div id="review-answer" class="review-answer hide">${item.translation}</div>
      <button type="button" id="show-answer">Показать перевод</button>
      <div id="review-actions" class="hide review-actions">
        <button type="button" id="forgot">Не помню</button>
        <button type="button" id="remember">Помню</button>
      </div>
    </div>`;
  $('show-answer').addEventListener('click', () => {
    reviewRevealed = true;
    $('review-answer').classList.remove('hide');
    $('show-answer').classList.add('hide');
    $('review-actions').classList.remove('hide');
  });
  $('forgot').addEventListener('click', () => answerReview(item.word, false));
  $('remember').addEventListener('click', () => answerReview(item.word, true));
}

function answerReview(w, correct){
  const item = saved.find(x => x.word === w);
  if (!item) { reviewIndex++; renderReviewCard(); return; }
  const current = Number(item.box) || 1;
  if (correct) {
    item.box = Math.min(5, current + 1);
    const days = REVIEW_INTERVALS[item.box];
    item.nextReview = Date.now() + days * 24 * 60 * 60 * 1000;
  } else {
    item.box = 1;
    item.nextReview = Date.now();
    // Ошибочные карточки ещё раз попадут в конец текущей сессии.
    reviewQueue.push(w);
  }
  save();
  reviewIndex++;
  renderReviewCard();
}

function exportWords(){
  const blob = new Blob([JSON.stringify(saved, null, 2)], {type:'application/json'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'citaj-srpski-moji-slova.json';
  a.click();
  URL.revokeObjectURL(url);
}

function importWords(event){
  const file = event.target.files && event.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = () => {
    try {
      const imported = JSON.parse(reader.result);
      if (!Array.isArray(imported)) throw new Error('bad');
      const clean = imported.filter(x => x && typeof x.word === 'string').map(x => ({
        word:x.word, translation:x.translation || DICT[x.word] || 'Перевод пока не добавлен',
        added:x.added || new Date().toISOString(), box:Number(x.box)||1, nextReview:x.nextReview || Date.now()
      }));
      saved = clean;
      save();
      words();
      alert('Слова загружены.');
    } catch(e) { alert('Не удалось прочитать резервную копию.'); }
  };
  reader.readAsText(file);
}

function removeWord(i){
  saved.splice(i,1);
  save();
  words();
}

// Навигация — без inline onclick, чтобы сайт одинаково работал на GitHub Pages и мобильном Chrome.
document.addEventListener("click", event => {
  const nav = event.target.closest("[data-v]");
  if (nav) {
    const v = nav.dataset.v;
    if (v === "texts") texts();
    if (v === "words") words();
    view(v);
    return;
  }

  const readerButton = event.target.closest(".read-text");
  if (readerButton) {
    openText(Number(readerButton.dataset.index));
    return;
  }

  const wordButton = event.target.closest(".word");
  if (wordButton) {
    word(wordButton.dataset.word);
    return;
  }

  const removeButton = event.target.closest(".remove-word");
  if (removeButton) {
    removeWord(Number(removeButton.dataset.index));
  }
});

save();
texts();
